from __future__ import absolute_import
from taf.selenium.gnb.oam.coam.vdu import pages


class Alarms(pages.Alarms):

    def __init__(self, driver, version):
        if not self._instance_dict:
            super(Alarms, self).__init__(driver, version)
            self._instance_dict.update({"Active Alarms": ActiveAlarmsPageV25R1(driver, version),
                                        "Historical Alarms": AlarmHistoryPageV25R1(driver, version),
                                        "Fault Toggling History": FaultTogglingHistoryPageV25R1(driver, version)})


class ActiveAlarmsPageV25R1(pages.ActiveAlarmsPage):
    MENU_ROUTE_LIST = ['bell', 'Alarm Management', 'Active Alarms']


class AlarmHistoryPageV25R1(pages.AlarmHistoryPage):
    MENU_ROUTE_LIST = ['bell', 'Alarm Management', 'Historical Alarms']


class FaultTogglingHistoryPageV25R1(pages.FaultTogglingHistoryPage):
    MENU_ROUTE_LIST = ['bell', 'Alarm Management', 'Fault Toggling History']
